  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 10;

// SPRING PRESETS
const SNAPPY = { damping: 18, stiffness: 220, mass: 0.7 };
const LIQUID = { damping: 22, stiffness: 110, mass: 1 };
const GENTLE = { damping: 24, stiffness: 90, mass: 1 };

// VIEWBOX FOR THE INLINE SVG UI
const VB = { x: 0, y: 0, w: 1198, h: 766 };

// DELTA BBOXES
const URL_FIELD = { x: 343, y: 371, w: 511, h: 31 };
const DROPDOWN_PANEL = { x: 343, y: 411, w: 511, h: 151 };
const NOTION_ROW = { x: 345, y: 423, w: 511, h: 16 };
const FORM_AREA = { x: 319, y: 211, w: 560, h: 344 };
const BUTTON_BBOX = { x: 798, y: 499, w: 57, h: 32 };
const SUCCESS_BBOX = { x: 466, y: 466, w: 374, h: 375 };

// CURSOR PATH (frame-based)
const CURSOR_KEYS = [
  { f: 0, x: 200, y: 700 },
  { f: 18, x: 600, y: 387 }, // url field
  { f: 40, x: 600, y: 387 },
  { f: 60, x: 600, y: 432 }, // notion row
  { f: 95, x: 600, y: 432 },
  { f: 130, x: 830, y: 515 }, // button
  { f: 165, x: 830, y: 515 },
  { f: 195, x: 700, y: 600 },
  { f: 280, x: 700, y: 600 },
];

const CLICKS = [
  { f: 22, x: 600, y: 387 },
  { f: 62, x: 600, y: 432 },
  { f: 132, x: 830, y: 515 },
];

function cursorPos(frame: number) {
  for (let i = 0; i < CURSOR_KEYS.length - 1; i++) {
    const a = CURSOR_KEYS[i];
    const b = CURSOR_KEYS[i + 1];
    if (frame >= a.f && frame <= b.f) {
      const t = (frame - a.f) / Math.max(1, b.f - a.f);
      const eased = Easing.inOut(Easing.cubic)(t);
      return {
        x: a.x + (b.x - a.x) * eased,
        y: a.y + (b.y - a.y) * eased,
      };
    }
  }
  const last = CURSOR_KEYS[CURSOR_KEYS.length - 1];
  return { x: last.x, y: last.y };
}

// Ambient drift (perlin-ish via sin combo)
function ambientDrift(frame: number, amp: number, period: number, seed: number) {
  return (
    Math.sin(frame / period + seed) * amp * 0.6 +
    Math.sin(frame / (period * 1.7) + seed * 2) * amp * 0.4
  );
}

