// ============================================================================
// CURSOR + CLICK RIPPLES (overlay)
// ============================================================================
const CursorOverlay: React.FC<{ startFrame: number }> = ({ startFrame }) => {
  const frame = useCurrentFrame() - startFrame;
  if (frame < 0) return null;
  const cur = cursorPos(frame);
  return (
    <svg
      viewBox={`0 0 ${VB.w} ${VB.h}`}
      style={{
        position: "absolute",
        inset: 0,
        width: "100%",
        height: "100%",
        pointerEvents: "none",
      }}
      preserveAspectRatio="xMidYMid meet"
    >
      {CLICKS.map((c, i) => {
        const dt = frame - c.f;
        if (dt < -2 || dt > 18) return null;
        const t = (dt + 2) / 20;
        const r = interpolate(t, [0, 1], [4, 56], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const op = interpolate(t, [0, 0.2, 1], [0, 0.6, 0], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        return (
          <circle
            key={i}
            cx={c.x}
            cy={c.y}
            r={r}
            fill="none"
            stroke={COLORS.orange}
            strokeWidth={2.5}
            opacity={op}
          />
        );
      })}
      <g
        transform={`translate(${cur.x}, ${cur.y})`}
        style={{ filter: "drop-shadow(0 2px 4px rgba(0,0,0,0.7))" }}
      >
        <path
          d="M0 0 L0 26 L7 19 L11 28 L15 26 L11 17 L20 17 Z"
          fill="white"
          stroke="#0a0a0b"
          strokeWidth={1.2}
          strokeLinejoin="round"
        />
      </g>
    </svg>
  );
};

